 1: ---
 2: # This playbook provisions given topology.
 3: 
 4: - name:  "schema check and Pre Provisioning Activities on topology_file"
 5:   hosts: localhost
 6:   gather_facts: False
 7:   roles:
 8:     - { role: 'common' }
 9: 
10: - name:  "Provisioning resources based on resource group type"
11:   hosts: localhost
12:   gather_facts: False
13:   roles:
14:     - { role: 'dummy', when: dummy_res_grps | length > 0 }
15:     - { role: 'nummy', when: nummy_res_grps | length > 0 }
16:     - { role: 'openstack', when: os_res_grps | length > 0  }
17:     - { role: 'aws', when: aws_res_grps | length > 0 }
18:     - { role: 'gcloud', when: gcloud_res_grps | length > 0 }
19:     - { role: 'libvirt', when: libvirt_res_grps | length > 0 }
20:     - { role: 'duffy', when: duffy_res_grps | length > 0}
21:     - { role: 'rackspace', when: rax_res_grps | length > 0 }
22:     - { role: 'beaker', when: bkr_res_grps | length > 0 }
23:     - { role: 'openshift', when: openshift_res_grps | length > 0 }
24:     - { role: 'ovirt', when: ovirt_res_grps | length > 0 }
25:     - { role: 'vmware', when: vmware_res_grps | length > 0 }
26: 
27: - name: "Writing contents to file"
28:   hosts: localhost
29:   gather_facts: False
30:   roles:
31:     - { role: 'gather_resources'}

